"use client";

/* eslint-disable @next/next/no-img-element -- QR is an ephemeral data URL generated by the trusted backend. */
import { FormEvent, useSyncExternalStore, useState } from "react";
import { useRouter } from "next/navigation";
import { completeAdminMFA, login } from "@/services/admin-api";

const subscribeToHydration = () => () => {};
const getClientHydration = () => true;
const getServerHydration = () => false;

export function AdminLoginForm() {
  const router = useRouter();
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [totp, setTotp] = useState("");
  const [recoveryCode, setRecoveryCode] = useState("");
  const [error, setError] = useState("");
  const [challenge, setChallenge] = useState("");
  const [setup, setSetup] = useState<{ qr?: string; secret?: string } | null>(null);
  const [recovery, setRecovery] = useState<string[]>([]);
  const [loading, setLoading] = useState(false);
  const hydrated = useSyncExternalStore(subscribeToHydration, getClientHydration, getServerHydration);

  const submit = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (loading) return;

    setLoading(true);
    setError("");
    try {
      if (!challenge) {
        const result = await login(email, password);
        // The password is no longer needed once the server has issued a challenge.
        setPassword("");
        setTotp("");
        setRecoveryCode("");
        setSetup(result.action === "mfa_setup_required"
          ? { qr: result.qr_code_data_url, secret: result.setup_secret }
          : null);
        setChallenge(result.challenge_token);
        return;
      }

      const result = await completeAdminMFA(challenge, totp, recoveryCode);
      setTotp("");
      setRecoveryCode("");
      sessionStorage.setItem("loja3d_admin_csrf", result.csrf_token);
      if (result.recovery_codes?.length) {
        setRecovery(result.recovery_codes);
        return;
      }
      router.push("/admin");
      router.refresh();
    } catch (cause) {
      // Failed attempts must not leave credentials ready to be reused accidentally.
      setPassword("");
      setTotp("");
      setRecoveryCode("");
      setError(cause instanceof Error ? cause.message : "Acesso negado.");
    } finally {
      setLoading(false);
    }
  };

  if (recovery.length) {
    return (
      <section className="admin-login-card">
        <span className="admin-kicker">Códigos de recuperação</span>
        <h1>Guarde agora</h1>
        <p>Eles não serão exibidos novamente.</p>
        <pre className="admin-recovery">{recovery.join("\n")}</pre>
        <button onClick={() => { router.push("/admin"); router.refresh(); }}>Concluir</button>
      </section>
    );
  }

  const mfaStep = Boolean(challenge);
  return (
    <form key={mfaStep ? "mfa" : "credentials"} className="admin-login-card" method="post" onSubmit={submit}>
      <span className="admin-kicker">Acesso restrito</span>
      <h1>{mfaStep ? setup ? "Ativar MFA" : "Segundo fator" : "Operação Loja 3D"}</h1>
      {!mfaStep ? (
        <>
          <p>Cloudflare Access e autenticação interna continuam obrigatórios.</p>
          <label>E-mail<input name="email" type="email" autoComplete="username" value={email} onChange={event => setEmail(event.target.value)} required /></label>
          <label>Senha<input name="password" type="password" autoComplete="current-password" value={password} onChange={event => setPassword(event.target.value)} minLength={12} required /></label>
        </>
      ) : (
        <>
          {setup?.qr && <img className="admin-qr" src={setup.qr} alt="QR Code para configurar o autenticador" />}
          {setup?.secret && <p>Chave manual: <code>{setup.secret}</code></p>}
          <label>Código do autenticador<input name="totp" type="text" inputMode="numeric" autoComplete="one-time-code" pattern="[0-9]{6}" maxLength={6} value={totp} onChange={event => setTotp(event.target.value)} /></label>
          {!setup && <label>Código de recuperação<input name="recovery_code" autoComplete="off" value={recoveryCode} onChange={event => setRecoveryCode(event.target.value)} /></label>}
        </>
      )}
      {error && <div className="admin-alert" role="alert">{error}</div>}
      <button disabled={loading || !hydrated}>{loading ? "Verificando…" : mfaStep ? "Confirmar fator" : "Continuar"}</button>
    </form>
  );
}
